                    match post_cs_j {
                        CombinerState::Reading(ReaderState::Guard { start, end, cur, val }) => {
                            let new_cur_idx = pre.combiner[node_id].get_Appending_cur_idx() + 1;
                            let tail = pre.combiner[node_id].get_Appending_tail();
                            assert((new_cur_idx > cur) || (tail <= cur));
                        },
                        CombinerState::Appending { cur_idx: cur_idx2, tail: tail2 } => {
                            let new_cur_idx = pre.combiner[node_id].get_Appending_cur_idx() + 1;
                            let tail = pre.combiner[node_id].get_Appending_tail();
                            assert((new_cur_idx >= tail2) || (tail <= cur_idx2));
                        },
                        _ => { }
                    }
                } else if j == node_id {
                    // j is the modified node, i is unchanged
                    // Need to check post_cs_i.no_overlap_with(post_cs_j)
                    match post_cs_i {
                        CombinerState::Appending { cur_idx: cur_idx2, tail: tail2 } => {
                            let new_cur_idx = pre.combiner[node_id].get_Appending_cur_idx() + 1;
                            let tail = pre.combiner[node_id].get_Appending_tail();
                            assert((cur_idx2 > new_cur_idx) || (tail2 <= new_cur_idx));
                        },
                        _ => { }
                    }
                } else {
                    // Neither i nor j changed, so the relationship remains the same
                    assert(pre_cs_i.no_overlap_with(pre_cs_j));
                    assert(post_cs_i.no_overlap_with(post_cs_j)); 
                }
            } else {
