                    // The bit was flipped to log_entry_alive_value(cur_idx, buffer_size)
                    // But since cur_idx >= post.tail (after the increment), 
                    // and we're checking for i >= post.tail, this shouldn't apply yet

                    // Actually, let's look more carefully: 
                    // pre.tail = post.tail - 1 (because we incremented cur_idx)
                    // pre.combiner[node_id] = Appending { cur_idx, tail: post.tail }
                    // We flipped the bit at log_entry_idx(cur_idx, buffer_size)
                    // And we're checking for i where post.tail <= i < ...

                    // Since cur_idx < pre.tail + 1 = post.tail, the flipped bit is at an index < post.tail
                    // Therefore, it doesn't affect our current assertion which checks i >= post.tail
                } else {
                    // The bit wasn't flipped, so it preserves the pre-state property
                    assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
                    // Since this index is >= post.tail, and no flip occurred here, it should stay the same
                    assert(post.alive_bits.dom().contains(log_entry_idx(i, post.buffer_size)));
                    // Need to be more careful - let's use the pre invariant
                    assert forall |j| pre.tail <= j < min_local_head_pre + pre.buffer_size
                        implies !log_entry_is_alive(pre.alive_bits, j, pre.buffer_size) by {
                        // This is the pre invariant
                    }
                    // But we're looking at post.tail = pre.tail + 1, so we need to adjust for that
                }
            } else {
                // The index i wasn't directly affected by the bit flip in this operation
                // So we can leverage the pre-state invariant
                // This requires a more careful argument based on which physical index maps to i

                // Key insight: Only one bit was flipped, at position log_entry_idx(cur_idx, buffer_size)
                // where cur_idx = pre.combiner[node_id].get_Appending_cur_idx()
                // For all other positions, the alive_bits remain unchanged

                if i >= pre.tail {
                    // These positions had !log_entry_is_alive in pre-state, and weren't flipped
                    // so they should maintain that property
                    assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
                } else {
                    // i < pre.tail, so we might be dealing with a wrapped-around index.
                    // Need to consider the modular arithmetic.
                }
            }

            // Let's approach this more systematically:
            // Pre invariant: forall i, pre.tail <= i < min_local_head_pre + pre.buffer_size ==> !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)
            // Post values: post.tail = pre.tail + 1, other values unchanged

            // We need to show: forall i, post.tail <= i < min_local_head_post + post.buffer_size ==> !log_entry_is_alive(post.alive_bits, i, post.buffer_size)

            // Let's prove for an arbitrary such i:
            // post.tail <= i < min_local_head_post + post.buffer_size
            // pre.tail + 1 <= i < min_local_head_pre + pre.buffer_size  (since min_local_head and buffer_size unchanged)
            // pre.tail <= i - 1 < min_local_head_pre + pre.buffer_size - 1
            // So i - 1 satisfies the pre invariant, thus !log_entry_is_alive(pre.alive_bits, i - 1, pre.buffer_size)

            // But we want to show !log_entry_is_alive(post.alive_bits, i, post.buffer_size)

            // The only difference between pre.alive_bits and post.alive_bits is at position:
            // log_entry_idx(pre.combiner[node_id].get_Appending_cur_idx(), pre.buffer_size)

            // If log_entry_idx(i, post.buffer_size) != log_entry_idx(pre.combiner[node_id].get_Appending_cur_idx(), pre.buffer_size),
            // then post.alive_bits[log_entry_idx(i, post.buffer_size)] == pre.alive_bits[log_entry_idx(i, post.buffer_size)],
            // so we can use the pre invariant.

            let flipped_position = log_entry_idx(pre.combiner[node_id].get_Appending_cur_idx() as int, pre.buffer_size);
            let target_position = log_entry_idx(i, post.buffer_size);

            if target_position != flipped_position {
                // Bit didn't change, so we can refer to the pre invariant
                // But we need to be more careful about the logical vs physical indexing
                assert(post.alive_bits[target_position] == pre.alive_bits[target_position]);
                // Need to show that pre.alive_bits[target_position] corresponds to !log_entry_is_alive for logical index i
            }
