#[inductive(append_flip_bit)]
fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) {
    // Proof for ranges_no_overlap invariant
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j
        implies post.combiner[i].no_overlap_with(post.combiner[j]) by {

        // The append_flip_bit transition only modifies node_id's combiner state,
        // changing it from Appending{cur_idx, tail} to Appending{cur_idx+1, tail}.
        // All other combiner states remain unchanged.

        if i == node_id || j == node_id {
            // One of the nodes is the one being modified
            if i == node_id && j != node_id {
                // i is the modified node, j is unchanged
                let old_cur_idx = pre.combiner[node_id].get_Appending_cur_idx();
                let tail = pre.combiner[node_id].get_Appending_tail();
                let new_cur_idx = old_cur_idx + 1;

                match post.combiner[j] {
                    CombinerState::Reading(ReaderState::Guard { start, end, cur, val }) => {
                        // Check that Appending{new_cur_idx, tail} doesn't overlap with the Guard
                        assert((new_cur_idx > cur) || (tail <= cur));
                    },
                    CombinerState::Appending { cur_idx: other_cur_idx, tail: other_tail } => {
                        // Check that Appending{new_cur_idx, tail} doesn't overlap with Appending{other_cur_idx, other_tail}
                        assert((new_cur_idx >= other_tail) || (tail <= other_cur_idx));
                    },
                    _ => { }
                }
            } else if j == node_id && i != node_id {
                // j is the modified node, i is unchanged
                let old_cur_idx = pre.combiner[node_id].get_Appending_cur_idx();
                let tail = pre.combiner[node_id].get_Appending_tail();
                let new_cur_idx = old_cur_idx + 1;

                match post.combiner[i] {
                    CombinerState::Appending { cur_idx: other_cur_idx, tail: other_tail } => {
                        // Check that Appending{other_cur_idx, other_tail} doesn't overlap with Appending{new_cur_idx, tail}
                        assert((other_cur_idx >= tail) || (other_tail <= new_cur_idx));
                    },
                    _ => { }
                }
            }
            // The i == node_id && j == node_id case is impossible since i != j
        } else {
            // Neither i nor j is the modified node, so their combiner states are unchanged
            // Since the invariant held in pre, it holds now
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        }
    }

    // Proof for upcoming_bits_are_not_alive invariant
    assert forall |i| post.tail <= i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat) + post.buffer_size
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {

        // In append_flip_bit, we have pre.tail + 1 = post.tail
        // We flipped the alive bit at position log_entry_idx(pre.combiner[node_id].get_Appending_cur_idx(), pre.buffer_size)
        // where pre.combiner[node_id].get_Appending_cur_idx() < pre.tail

        let flipped_logical_idx = pre.combiner[node_id].get_Appending_cur_idx() as int;
        let flipped_physical_idx = log_entry_idx(flipped_logical_idx, pre.buffer_size);

        // Consider any i such that post.tail <= i < min_local_head + post.buffer_size
        // This is equivalent to pre.tail + 1 <= i < min_local_head + pre.buffer_size

        let phys_idx = log_entry_idx(i, post.buffer_size);

        if phys_idx != flipped_physical_idx {
            // This physical position was not flipped, so post.alive_bits[phys_idx] = pre.alive_bits[phys_idx]
            // From pre invariant: since pre.tail <= i, we have !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)
            // So post.alive_bits[phys_idx] != log_entry_alive_value(i, post.buffer_size)
            // Thus !log_entry_is_alive(post.alive_bits, i, post.buffer_size)
            assert(post.alive_bits[phys_idx] == pre.alive_bits[phys_idx]);
        } else {
            // This physical position was flipped. We need to check that this case is actually impossible
            // or that it still satisfies the property.

            // Since we're considering i where i >= post.tail = pre.tail + 1,
            // and the flipped index was flipped_logical_idx < pre.tail,
            // we have flipped_logical_idx < pre.tail <= i - 1 < i.
            //
            // However, because of modular arithmetic, it's possible that 
            // log_entry_idx(flipped_logical_idx, buffer_size) = log_entry_idx(i, buffer_size)
            // even when flipped_logical_idx != i.
            //
            // But we can show that this leads to a contradiction with our invariant assumptions:
            //
            // We're assuming i >= post.tail, so physically this corresponds to a slot that
            // should still be marked as "not alive" according to the invariant.
            // The fact that we flipped a bit corresponding to a logically earlier index
            // doesn't change that.
            //
            // More precisely, by the pre invariant, all positions >= pre.tail satisfy the property.
            // The append_flip_bit transition only affects positions < pre.tail.

            // Actually, let's step back and reconsider what we're trying to prove:
            // Pre invariant says: for all j, if pre.tail <= j < min_local_head + pre.buffer_size, then !log_entry_is_alive(pre.alive_bits, j, pre.buffer_size)
            // Post values: post.tail = pre.tail + 1
            // Post invariant to prove: for all i, if post.tail <= i < min_local_head + post.buffer_size, then !log_entry_is_alive(post.alive_bits, i, post.buffer_size)

            // That is: for all i, if pre.tail + 1 <= i < min_local_head + pre.buffer_size, then !log_entry_is_alive(post.alive_bits, i, pre.buffer_size)

            // Now note that the append_flip_bit operation flips the bit ONLY at the physical position
            // corresponding to logical index flipped_logical_idx = pre.combiner[node_id].get_Appending_cur_idx()
            // where flipped_logical_idx < pre.tail (from the transition requirements)

            // For any i such that pre.tail + 1 <= i < min_local_head + pre.buffer_size,
            // we have i >= pre.tail + 1 > flipped_logical_idx.

            // If i and flipped_logical_idx map to different physical positions under log_entry_idx,
            // then post.alive_bits[log_entry_idx(i, pre.buffer_size)] = pre.alive_bits[log_entry_idx(i, pre.buffer_size)],
            // so !log_entry_is_alive(post.alive_bits, i, pre.buffer_size) follows from the pre invariant.

            // The tricky case is when they map to the same physical position, i.e.,
            // log_entry_idx(i, pre.buffer_size) = log_entry_idx(flipped_logical_idx, pre.buffer_size).

            // This happens when i ≡ flipped_logical_idx (mod pre.buffer_size).
            // Since i >= pre.tail + 1 and flipped_logical_idx < pre.tail, and pre.buffer_size = LOG_SIZE is very large,
            // the only way for this congruence to hold is if i = flipped_logical_idx + k * pre.buffer_size for some k >= 1.

            // But then i >= flipped_logical_idx + pre.buffer_size >= pre.tail + pre.buffer_size.
            // On the other hand, we're considering i < min_local_head + pre.buffer_size.
            // By another invariant, min_local_head <= pre.tail, so min_local_head + pre.buffer_size <= pre.tail + pre.buffer_size.
            // Hence i < pre.tail + pre.buffer_size. Contradiction.

            // Therefore, this case is actually impossible.
            assert(false); // If we reach here, there's a contradiction in our case analysis
        }
    }
}

