#[inductive(append_flip_bit)]
fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) {
    let cur_idx = pre.combiner[node_id].get_Appending_cur_idx() as int;

    // Show that the key cur_idx is not already in contents (for the deposit operation)
    assert(!pre.contents.dom().contains(cur_idx));

    // Show that all necessary preconditions for map_min_value_smallest are met  
    assert(forall |i: nat| i <= (pre.num_replicas - 1) as nat ==> pre.local_versions.contains_key(i));

    // ranges_no_overlap
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j
                   implies post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // The append_flip_bit transition modifies only node_id's combiner state
        // from Appending { cur_idx, tail } to Appending { cur_idx + 1, tail }

        if i == node_id {
            // i is the modified node
            if let CombinerState::Appending{cur_idx: other_cur_idx, tail: other_tail} = post.combiner[j] {
                // Check overlap with another Appending state
                let new_cur_idx = cur_idx + 1;
                assert((new_cur_idx >= other_tail) || (post.tail <= other_cur_idx));
            } else if let CombinerState::Reading(ReaderState::Guard{cur, ..}) = post.combiner[j] {
                // Check overlap with a Guard state
                let new_cur_idx = cur_idx + 1;
                assert((new_cur_idx > cur) || (post.tail <= cur));
            }
            // Other cases (Idle, Advancing*) trivially don't overlap with Appending
        } else if j == node_id {
            // j is the modified node, symmetric to above
            if let CombinerState::Appending{cur_idx: other_cur_idx, tail: other_tail} = post.combiner[i] {
                let new_cur_idx = cur_idx + 1;
                assert((other_cur_idx >= post.tail) || (other_tail <= new_cur_idx));
            }
            // Other cases handled by pre invariant
        } else {
            // Neither i nor j was modified, so their relationship is preserved from pre state
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        }
    };

    // upcoming_bits_are_not_alive
    let min_local_head = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
    assert forall |i| post.tail <= i < min_local_head + post.buffer_size
                   implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        let flipped_pos = log_entry_idx(cur_idx, pre.buffer_size);
        let check_pos = log_entry_idx(i, post.buffer_size);

        if flipped_pos != check_pos {
            // Position wasn't flipped, so bit value unchanged
            assert(post.alive_bits[check_pos] == pre.alive_bits[check_pos]);
            // By pre invariant: !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)
            // Since alive bit unchanged: !log_entry_is_alive(post.alive_bits, i, post.buffer_size)
        } else {
            // Same physical position. Since cur_idx < pre.tail (requirement of transition)
            // and we're checking i >= post.tail = pre.tail, this should be impossible
            // unless there's wraparound modulo buffer_size.
            //
            // If log_entry_idx(cur_idx, buffer_size) = log_entry_idx(i, buffer_size)
            // then cur_idx ≡ i (mod buffer_size).
            // Since cur_idx < pre.tail ≤ i, we must have i = cur_idx + k * buffer_size for k ≥ 1.
            // But then i ≥ cur_idx + buffer_size ≥ pre.tail (since cur_idx < pre.tail),
            // and buffer_size is huge (512K), so i would be way beyond the valid range.
            assert(false);
        }
    };
}

