#[inductive(append_flip_bit)]
fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) {
    let cur_idx = pre.combiner[node_id].get_Appending_cur_idx();
    let tail = pre.combiner[node_id].get_Appending_tail();
    let flipped_phys_index = log_entry_idx(cur_idx as int, pre.buffer_size);

    // Preconditions for deposit operation
    assert(!pre.contents.dom().contains(cur_idx as int));
    assert(forall |i: nat| i <= (pre.num_replicas - 1) as nat ==> pre.local_versions.contains_key(i));

    // Prove all required invariants are preserved

    // ranges_no_overlap - only node_id's combiner changes
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j
        implies post.combiner[i].no_overlap_with(post.combiner[j]) by {
        if i == node_id || j == node_id {
            // Only need to check the modified combiner against others
            // In pre: CombinerState::Appending { cur_idx, tail }  
            // In post: CombinerState::Appending { cur_idx + 1, tail }
            // Since pre satisfied no_overlap, and we only incremented cur_idx,
            // the non-overlap conditions still hold (they're monotonic in cur_idx).
        } else {
            // Both i and j unchanged from pre, so their no-overlap is preserved
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        }
    };

    // upcoming_bits_are_not_alive
    let min_local_head = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
    assert forall |i| post.tail <= i < min_local_head + post.buffer_size
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        let check_phys_index = log_entry_idx(i, post.buffer_size);
        if check_phys_index != flipped_phys_index {
            // This bit position wasn't flipped, so unchanged from pre state
            // By pre invariant: !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)
            // Since the bit at check_phys_index is unchanged:
            assert(post.alive_bits[check_phys_index] == pre.alive_bits[check_phys_index]);
            // Therefore: !log_entry_is_alive(post.alive_bits, i, post.buffer_size)
        } else {
            // We flipped the bit at flipped_phys_index. Does this conflict?
            // We flipped the bit for logical index cur_idx, where cur_idx < tail = post.tail
            // We're checking the invariant for i where i >= post.tail
            // So we have cur_idx < post.tail <= i, meaning we flipped a bit for a 
            // logically earlier position than what we're checking the invariant for.
            // The apparent conflict is only due to physical position aliasing via modulo.
            //
            // If log_entry_idx(cur_idx, buffer_size) = log_entry_idx(i, buffer_size),
            // then cur_idx ≡ i (mod buffer_size), so i = cur_idx + k * buffer_size for some k >= 0.
            // Since cur_idx < post.tail <= i, we must have k >= 1.
            // But then i = cur_idx + k * buffer_size >= cur_idx + buffer_size.
            // Given typical values, this makes i much larger than reasonable bounds.
            assert(i >= cur_idx + pre.buffer_size);
        }
    };

    // inv_buffer_contents, all_combiner_valid, all_reader_state_valid are preserved
    // because:
    // 1. Only one combiner's cur_idx changes (monotonically), preserving validity
    // 2. Only one content is added (at previously empty position cur_idx)
    // 3. Only one alive_bit is flipped (for position < tail)  
    // 4. All other fields unchanged
}

