#[inductive(append_flip_bit)]
fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) {
    let cur_idx = pre.combiner[node_id].get_Appending_cur_idx();
    let tail = pre.combiner[node_id].get_Appending_tail();

    // Technical preconditions

    // 1. Safety condition: key must be absent from map before deposit
    assert(!pre.contents.contains_key(cur_idx as int));

    // 2. Precondition for map_min_value_smallest in deposit operation clause
    assert(forall |i: nat| i <= (pre.num_replicas - 1) as nat ==> pre.local_versions.contains_key(i));

    // Essential invariant proofs

    // ranges_no_overlap - We modify only node_id's combiner state
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j
        implies post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // Cases:
        if i == node_id && j != node_id {
            // Need to show post.combiner[node_id].no_overlap_with(post.combiner[j])
            // where post.combiner[node_id] = Appending { cur_idx + 1, tail }
            // and post.combiner[j] = pre.combiner[j] (unchanged)
            //
            // By pre invariant, pre.combiner[node_id].no_overlap_with(pre.combiner[j]).
            // Since pre.combiner[node_id] = Appending { cur_idx, tail }, this means:
            //   - if pre.combiner[j] is Reading(Guard{..., cur, ...}), then (cur_idx > cur) || (tail <= cur)
            //   - if pre.combiner[j] is Appending { cur_idx2, tail2 }, then (cur_idx >= tail2) || (tail <= cur_idx2)
            //
            // In post, we have Appending { cur_idx + 1, tail }.  
            // - For Guard case: (cur_idx + 1 > cur) || (tail <= cur). Since (cur_idx > cur) || (tail <= cur) in pre, this still holds.
            // - For Appending case: (cur_idx + 1 >= tail2) || (tail <= tail2). Since (cur_idx >= tail2) || (tail <= tail2) in pre, this still holds.
        } else if j == node_id && i != node_id {
            // Symmetric to the above case
        } else {
            // Both i and j are unchanged from pre state, so their non-overlap relation is preserved
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        }
    };

    // upcoming_bits_are_not_alive - we only flip a bit at position log_entry_idx(cur_idx, buffer_size)
    // where cur_idx < pre.tail = post.tail. We need to show that for i >= post.tail, the corresponding 
    // alive bit is still false.
    let min_local_head = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
    assert(min_local_head == map_min_value(post.local_versions, (post.num_replicas - 1) as nat)); // unchanged

    assert forall |i| post.tail <= i < min_local_head + post.buffer_size 
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        let logical_i = i;
        let physical_pos = log_entry_idx(logical_i, post.buffer_size);
        let flipped_physical_pos = log_entry_idx(cur_idx as int, pre.buffer_size);

        if physical_pos != flipped_physical_pos {
            // The bit at this physical position was unchanged
            // So post.alive_bits[physical_pos] = pre.alive_bits[physical_pos]
            // By pre invariant: !log_entry_is_alive(pre.alive_bits, logical_i, pre.buffer_size)  
            // Therefore: !log_entry_is_alive(post.alive_bits, logical_i, post.buffer_size)
        } else {
            // We flipped the bit that corresponds to this logical position.
            // But this should be impossible under normal operation:
            // cur_idx < pre.tail <= logical_i, and physical_pos == flipped_physical_pos
            // means cur_idx ≡ logical_i (mod buffer_size)
            // So logical_i = cur_idx + k * buffer_size for some k ≥ 0.
            // Since cur_idx < pre.tail ≤ logical_i, we must have k ≥ 1.
            // Given buffer_size = 512*1024, logical_i would be enormous.
            // In fact, the invariant restricts logical_i < min_local_head + buffer_size.
            // Since pre.combiner_valid gives us cur_idx ≥ pre.local_versions[node_id] ≥ min_local_head,
            // we would have logical_i = cur_idx + k*buffer_size ≥ min_local_head + buffer_size,
            // conflicting with logical_i < min_local_head + buffer_size.
            assert(false);
        } 
    };
}
